import uuid
import time
from typing import Optional

class TokenService:
    def __init__(self, redis_client=None, ttl_seconds: int = 86400):
        self.redis = redis_client
        self.ttl = ttl_seconds
        self._in_memory_blacklist = set()

    def generate_token_pair(self, user_id: str) -> dict:
        access_token = f"access_{uuid.uuid4().hex}"
        refresh_token = f"refresh_{uuid.uuid4().hex}"
        return {"access_token": access_token, "refresh_token": refresh_token, "user_id": user_id, "created_at": time.time()}

    def revoke_refresh_token(self, refresh_token: str) -> bool:
        if self.redis:
            self.redis.setex(f"blacklist:{refresh_token}", self.ttl, "revoked")
        else:
            self._in_memory_blacklist.add(refresh_token)
        return True

    def is_token_blacklisted(self, refresh_token: str) -> bool:
        if self.redis:
            return bool(self.redis.exists(f"blacklist:{refresh_token}"))
        return refresh_token in self._in_memory_blacklist

    def rotate_refresh_token(self, old_refresh_token: str, user_id: str) -> dict:
        if self.is_token_blacklisted(old_refresh_token):
            raise ValueError("Token has been revoked or already rotated!")
        self.revoke_refresh_token(old_refresh_token)
        return self.generate_token_pair(user_id)
